ROOT=Path('/mnt/data/hydro_v6')
REQS=[]
def add(module,priority,feature,inputs,rule,accept,owner='engineering'):
    nr=sum(1 for r in REQS if r['module']==module)+1
    codes={'HydroForecast':'HF','CascadeEconomics':'CE','TurbineReliability':'TR','GridLossPlanner':'GL','HeatNetEconomics':'HN','HydroCAPEX':'HC','CorePlatform':'CORE'}
    code=codes[module]+'-'+str(nr).zfill(3)
    REQS.append(dict(id=code,module=module,priority=priority,feature=feature,inputs=inputs,rule=rule,acceptance=accept,owner=owner,status='PLANNED',sourceType='DESIGN_HYPOTHESIS',pilotScope='MAGADAN_CANDIDATE'))
