def export():
    export_dir=ROOT/'docs';export_dir.mkdir(exist_ok=True)
    for fname,items,headers in [
      ('V6_REQUIREMENTS.csv',REQS,list(REQS[0])),
      ('V6_DATA_DICTIONARY.csv',[dict(zip(['field','type','unit','description','classification','proposed_source','missing_policy'],a)) for a in DATA],['field','type','unit','description','classification','proposed_source','missing_policy']),
      ('V6_API_CONTRACTS.csv',[dict(zip(['method','path','request','response','negative_test'],a)) for a in API],['method','path','request','response','negative_test'])]:
      with (export_dir/fname).open('w',newline='',encoding='utf-8-sig') as f:
        w=csv.DictWriter(f,fieldnames=headers);w.writeheader();w.writerows(items)
    (export_dir/'V6_MASTER_SPEC.json').write_text(json.dumps({'requirements':REQS,'data_dictionary':DATA,'api':API,'raci':RACI,'pilots':PILOTS,'sources':SOURCES,'status':'PROPOSED_REQUIREMENTS_NOT_VALIDATED'},ensure_ascii=False,indent=2),encoding='utf-8')
    print('Requirements:',len(REQS),'Data:',len(DATA),'API:',len(API),'RACI:',len(RACI))
if __name__=='__main__':export()
